package com.clinicready.document;

import java.io.IOException;
import java.io.InputStream;

/**
 * Where document bytes live. Keys are opaque and generated by the server, never taken from the
 * client. The default implementation writes to a local directory/volume; an S3/MinIO
 * implementation can replace it without touching {@link DocumentService}.
 */
interface DocumentStorage {

    /** Result of a successful {@link #store}. */
    record StoredFile(long sizeBytes, String sha256) {
    }

    /**
     * Stores the stream under {@code key} and returns its size and lowercase hex SHA-256. Nothing is
     * left behind if it fails.
     *
     * @throws FileTooLargeException if the stream is longer than {@code maxBytes}
     */
    StoredFile store(String key, InputStream content, long maxBytes) throws IOException;

    /** @throws java.nio.file.NoSuchFileException if there is no such object */
    InputStream open(String key) throws IOException;

    /** Best effort; a missing object is not an error. */
    void delete(String key);
}
